package com.ebuddy.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="user_session") public class SessionEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="session_id") UUID id; @Column(name="user_id",nullable=false) UUID userId; @Column(name="token_hash",nullable=false,unique=true) byte[] tokenHash; @Column(name="client_type",nullable=false,length=12) String clientType; @Column(name="device_label",length=80) String deviceLabel; @Column(name="issued_at",nullable=false) Instant issuedAt=Instant.now(); @Column(name="expires_at",nullable=false) Instant expiresAt; @Enumerated(EnumType.STRING) @Column(nullable=false) SessionState state=SessionState.active; protected SessionEntity(){} public SessionEntity(UUID u,byte[] h,String c,String d,Instant e){userId=u;tokenHash=h;clientType=c;deviceLabel=d;expiresAt=e;} public UUID getUserId(){return userId;} }
